def _resident_gram512(left, right):
    out = fnp.empty((1024, 1024), dtype=fnp.float32)
    part = _mm(left[:512, :], right[:, :512])
    fnp.copyto(out[:512, :512], part)
    del part
    part = _mm(left[:512, :], right[:, 512:])
    fnp.copyto(out[:512, 512:], part)
    fnp.copyto(out[512:, :512], part.T)
    del part
    part = _mm(left[512:, :], right[:, 512:])
    fnp.copyto(out[512:, 512:], part)
    del part
    return out


